/*---------------------------------------------------------
 * GrCreateStipple -
 *	Create a stipple pattern.
 *
 * Results:	returns (opaque) pointer to Pixmap
 *
 *---------------------------------------------------------
 */
void * 
GrCreateStipple(char **rows)
		/* row1 row2 ... 
		 * each row is string of '1's and '0's
		 * row list terminated by NULL pointer. 
		 */
{
  int dimX, dimY;
  Pixmap pixmap;
  Pixmap *result;
  int x,y;

  /* compute dimensions */
  dimX= strlen(rows[0]); 
  dimY=0;
  while(rows[dimY]) dimY++;

  pixmap = XCreatePixmap(grXdpy, grXMainWin, 
			 dimX, dimY,  /* width, height */
			 1);    /* depth */

  for (y = 0; y < dimY; y++) 
  {
    char *row = rows[y];
    assert(strlen(row)==dimX);

    for (x = 0; x < dimX; x++) 
    {
      XSetForeground(grXdpy, grXGCBitMap, 
		     row[x]=='1' ? 1 : 0);
      XDrawPoint(grXdpy, pixmap, grXGCBitMap, 
		 x, y);
    }
  }

  /* return opaque pointer so caller does not rely on fact that
   * Pixmaps are ints. (for clean porting to NT etc.)
   */
  result = malloc(sizeof(Pixmap));
  *result = pixmap;
  return result;
}


/*---------------------------------------------------------
 * GrCreateStippleFromPixmapPlane -
 *	Create a stipple pattern.
 *
 * Results:	returns (opaque) pointer to Pixmap
 *
 *---------------------------------------------------------
 */
void * 
GrCreateStippleFromPixmapPlane(void *pixmapO,  
			                         /* opaque pointer to pixmap */
			       int planeMask)
                                                 /* plane in pixmap to copy 
						  * to stipple
						  */
{
  Pixmap stipple;
  Pixmap *result;
  GrDrawable *pixmap = pixmapO;

  stipple = XCreatePixmap(grXdpy, grXMainWin, 
			 pixmap->gd_width,
			 pixmap->gd_height,
			 1);    /* depth */

  XSetForeground(grXdpy, grXGCBitMap, 1);
  XSetBackground(grXdpy, grXGCBitMap, 0);

  if(GrColorMapped)  planeMask = grPixelsAll[planeMask] & ~grOtherAll;

  XCopyPlane(grXdpy, pixmap->gd_drawable, stipple, grXGCBitMap,
	     0, 0, /* src x y */
	     pixmap->gd_width,
	     pixmap->gd_height,
	     0, 0, /* dest x y */
	     planeMask); 

  /* return opaque pointer so caller does not rely on fact that
   * Pixmaps are ints. (for clean porting to NT etc.)
   */
  result = malloc(sizeof(Pixmap));
  *result = stipple;
  return result;
}


/*---------------------------------------------------------
 * GrCreateLinePattern --
 *
 *      Convert pattern string to X dash specification.
 *
 *---------------------------------------------------------
 */

#define GR_PREV(i) ( i==0 ? dim -1 : i-1 )
#define GR_NEXT(i) ( i==dim-1 ? 0 : i+1 )

void *GrCreateLinePattern(char *pattern) 
                                    /* string of '0's and '1's defining pattern */
{   
  int i;
  char dashList[1000];
  int numDashes = 0;
  int offset = 0;
  int pos = 0;
  int dim = strlen(pattern);

  LinePattern *lp;

  /* if all 1s or all 0s, return NULL */
  {
    int one = False;
    int zero = False;
    for(i=0; i<dim; i++)
    {
      if(pattern[i] == '1')
      {
	one = True;
      }
      else
      {
	zero = True;
      }
      if(one && zero) break;
    }
    if(!one || !zero) return NULL;
  }

  /* "rotate" pattern to beginning of on-dash (1s) */ 
  while(pattern[pos]=='0' || pattern[GR_PREV(pos)]=='1')
  {
    pos = GR_PREV(pos);
    offset++;
  }

  /* loop around pattern generating dashes */
  {
    int length = 1;
    int initialPos = pos;
    pos = GR_NEXT(pos);

    while(pos != initialPos)
    {
      if(pattern[pos] == pattern[GR_PREV(pos)])
      {
	length++;
      }
      else
      {
	dashList[numDashes++] = length;
	length = 1;
      }

      pos = GR_NEXT(pos);

    }
    dashList[numDashes++] = length;
  }

  /* create the LinePattern */
  lp = (LinePattern *) malloc(sizeof(LinePattern));
  lp->lp_dashOffset = offset;
  lp->lp_dashNum = numDashes;

  lp->lp_dashList = (char *) malloc(numDashes);
  for(i=0; i<numDashes;i++) lp->lp_dashList[i] = dashList[i];

  return lp;
} 


/*
 * ----------------------------------------------------------------------------
 *
 * GrRGBToPixel --
 *      
 *      convert rgb to pixel value.
 *
 * ----------------------------------------------------------------------------
 */
#define ROUND(x) ((int) (((x)>0)?(x)+.5:(x)-.5 ))
int
GrRGBToPixel(int r,      /* 0<=r,g,b<=255 */
	     int g,
	     int b)
{
  XColor color;
  double scaleFactor = 65535.0 / 255.0;

  assert(!GrColorMapped);

  color.red   = ROUND(r*scaleFactor);
  color.green = ROUND(g*scaleFactor);
  color.blue  = ROUND(b*scaleFactor);

  XAllocColor(grXdpy, grXcmap, &color);
  return color.pixel;
}  

/*
 * ----------------------------------------------------------------------------
 *
 * GrColorMapWrite --
 *      
 *      Set a colormap entry.
 *
 * ----------------------------------------------------------------------------
 */
void
GrColorMapWrite(int c,       /* entry */ 
		int r,       /* color */
		int g,
		int b)
{
      XColor xColor;

      if(!GrColorMapped)
      {
	fprintf(stderr,
		"Warning:  Colormap write in non-color-mapped mode.\n");
	return;
      }

      xColor.pixel = grPixelsColor[c];
      xColor.red   = r<<8;
      xColor.green = g<<8;
      xColor.blue  = b<<8;
      xColor.flags = DoRed|DoGreen|DoBlue;

      XStoreColor(grXdpy, grXcmap, &xColor);
}

/*
 * ----------------------------------------------------------------------------
 * GrTextBBox --
 *
 *	Determine bounding box of a text string in pixels 
 *      origin is left end of base line. 
 *
 * ----------------------------------------------------------------------------
 */

void
GrTextBBox(char *text, 
	   int fontSize,  /* ordinal of font */
	   int rot,       /* rotation (0,90,180,270) */
	   int *xbot, 
	   int *ybot,
	   int *xtop,
	   int *ytop)
                        /* results filled in here */
     
{
    XCharStruct overall;
    int dir,fa,fd;
    XFontStruct *font;

    /* find font corresponding to size */
    if(fontSize>GrMaxFontSize) fontSize = GrMaxFontSize;


    if(fontSize<0)
    {
      /* null text */
      *xbot=0;
      *ybot=0;
      *xtop=0;
      *ytop=0;
    }

    font = grXFonts[fontSize];

    XTextExtents(font, text, strlen(text), &dir, &fa, &fd, &overall);

    if(rot == 0) 
    {
      /* (x,y) */
      *xbot = -overall.lbearing - 1;
      *ybot = -overall.descent;

      *xtop = overall.width - overall.lbearing;
      *ytop = overall.ascent;
    }
    else if (rot == 90)
    {
      /* (-y,x) */
      *xbot = overall.descent;
      *ybot = -overall.lbearing - 1;

      *xtop = -overall.ascent;
      *ytop = overall.width - overall.lbearing;
    }
    else if (rot == 180)
    {
      /* (-x,-y) */
      *xbot = overall.lbearing + 1;
      *ybot = overall.descent;

      *xtop = overall.lbearing - overall.width;
      *ytop = -overall.ascent;
    }
    else if (rot == 270)
    {
      /* (y,-x) */
      *xbot = -overall.descent;
      *ybot = overall.lbearing + 1;

      *xtop = overall.ascent;
      *ytop = overall.lbearing - overall.width;
    }
    else
    {
      /* unsupported rotation */
      assert(False);
    }
}


/*
 * ----------------------------------------------------------------------------
 *
 * GrSetDrawable --
 *      
 *      Set window or pixmap to direct output to.
 *      (Can specify translation to apply to all input coordinates.)
 *
 * ----------------------------------------------------------------------------
 */
void
GrSetDrawable(void *drawable)  /* GrDrawable for window or pixmap */ 
{
  GrDrawable* gd = (GrDrawable*)drawable;

  /* flush pending graphics ops before changing context */
  if(grXWin != gd->gd_drawable) grFlushInternal();

  grXWin = gd->gd_drawable;
  grYAdjust = gd->gd_height - 1;
  grCurGD = gd;
}

/*
 * ----------------------------------------------------------------------------
 * grSameRect -- 
 *
 *  utility procedure to compare two rectangles 
 *  (rectangle is array of 4 ints)
 *
 * ----------------------------------------------------------------------------
 */
static bool grSameRect(int *r1, int *r2) 
{
  return (r1[0]==r2[0] &&
	  r1[1]==r2[1] &&
	  r1[2]==r2[2] &&
	  r1[3]==r2[3]);
}


/*
 * ----------------------------------------------------------------------------
 * grCopyRect -- 
 *
 *  utility procedure to copy one rect to another
 *  (rectangle is array of 4 ints)
 *
 * ----------------------------------------------------------------------------
 */
static void grCopyRect(int *src, int *dest) 
{
  dest[0]=src[0];
  dest[1]=src[1];
  dest[2]=src[2];
  dest[3]=src[3];
}

/*
 * ----------------------------------------------------------------------------
 * GrSetClipRect --
 *
 *	Causes subsequent graphics to be clipped to specified region of 
 *      window.
 *
 *      NULL arg resets clipping to entire window.
 *
 *      Clip area expanded one pixel to left and bottom, to not clip
 *      rectangles that were expanded from 0 pixel width/height.
 *
 * ----------------------------------------------------------------------------
 */
void
GrSetClipRect(int *rect)
                     /* x1 y1 x2 y2 or NULL */
{
  static int clipRect[4];
  int needClip;
  int xbot, ybot, xtop, ytop;  /* new clip rect */

  /* filter redundant sets */
  if((!rect && !grCurClipRect) ||
     (rect && grCurClipRect && grSameRect(rect,grCurClipRect))
     ) return;

  /* clip rect to drawable, and check if actually full window */
  needClip = False;
  if(rect)
  {
    /* xbot */
    if(rect[0]<=0)
    {
      xbot = 0;
    }
    else
    {
      xbot = rect[0];
      needClip = True;
    }

    /* ybot */
    if(rect[1]<=0)
    {
      ybot = 0;
    }
    else
    {
      ybot = rect[1];
      needClip = True;
    }

    /* xtop */
    if(rect[2]>=grCurGD->gd_width-1)
    {
      xtop = grCurGD->gd_width-1;
    }
    else
    {
      xtop = rect[2];
      needClip = True;
    }

    /* ytop */
    if(rect[3]>=grCurGD->gd_height-1)
    {
      ytop = grCurGD->gd_height-1;
    }
    else
    {
      ytop = rect[3];
      needClip = True;
    }
  }
  else
  {
    /* make gcc happy */
    xbot = ybot = xtop = ytop = 0;
  }

  /* last chance to avoid redundant set */
  if((!needClip && !grCurClipRect) || 
     (needClip && 
      grCurClipRect && 
      xbot == grCurClipRect[0] &&
      ybot == grCurClipRect[1] &&
      xtop == grCurClipRect[2] &&
      ytop == grCurClipRect[3])) return;
 				    
  /* flush queued graphics operations before changing context */
  grFlushInternal();

  if(!needClip)
  {
    grCurClipRect = NULL;
    XSetClipMask(grXdpy, grXGC, None);
  }
  else
  {
    XRectangle xRect;
    int clipOriginX, clipOriginY;

    clipRect[0] = xbot; 
    clipRect[1] = ybot; 
    clipRect[2] = xtop; 
    clipRect[3] = ytop; 
    grCurClipRect = clipRect;
    
    /* convert to origin and X-rectangle */
    clipOriginX = grMax2BufX(xbot);
    clipOriginY = grMax2BufY(ytop);
    xRect.x = 0; 
    xRect.y = 0;
    xRect.width =  xtop - xbot + 1;
    xRect.height = ytop - ybot + 1;

    XSetClipRectangles(grXdpy, 
		       grXGC, 
		       clipOriginX,  /* offset of clip rect from top right corner */
		       clipOriginY,  
		       &xRect,       
		       1,            /* just one rect */
		       3);           /* how we sorted our rect :-) */
  }
}

/*
 * ----------------------------------------------------------------------------
 * GrSetFontSize --
 *
 *	Set text font. (size=0,1,2,3  - in order of increasing size)
 *
 * ----------------------------------------------------------------------------
 */
void
GrSetFontSize(int size)
{
   /* filter redundant sets */ 
  if(size == grCurFontSize) return;
  grCurFontSize = size;

  /* don't need grFlushInternal() since font does not impact lines or rects */
  if(size>GrMaxFontSize) size = GrMaxFontSize;
  assert(0<=size);
  XSetFont(grXdpy, grXGC, grXFonts[size]->fid); 
}

/*
 * ----------------------------------------------------------------------------
 * GrFontHeightToIndex --
 *
 *	Get index of largest available font where no character exceeds
 *      given height (in pixels).
 *
 * ----------------------------------------------------------------------------
 */
int GrFontHeightToIndex(int height)
{
  if(height>=GR_MAX_FONT_DIM) return GrMaxFontSize;
  return grFontHeightToIndexTable[height];
}

/*
 * ----------------------------------------------------------------------------
 * GrFontWidthToIndex --
 *
 *	Get index of largest available font where no character exceeds
 *      given width (in pixels).
 *
 * ----------------------------------------------------------------------------
 */
int GrFontWidthToIndex(int width)
{
  if(width>=GR_MAX_FONT_DIM) return GrMaxFontSize;
  return grFontWidthToIndexTable[width];
}

/*
 * ----------------------------------------------------------------------------
 * GrSetFontSizeNew --
 *
 *	Set font to largest available font where no character
 *      exceeds specified pixel height and width.
 *
 * ----------------------------------------------------------------------------
 */
void
GrSetFontSizeNew(int height, int width)
{
  int size = MIN(GrFontHeightToIndex(height),GrFontWidthToIndex(width));

   /* filter redundant sets */ 
  if(size == grCurFontSize) return;


  /* don't need grFlushInternal() since font does not impact lines or rects */
  if(size>GrMaxFontSize) size = GrMaxFontSize;
  grCurFontSize = size;

  if(grCurFontSize>=0) XSetFont(grXdpy, grXGC, grXFonts[size]->fid); 
}


/*---------------------------------------------------------
 * GrDrawText ---
 *
 *      Draw a text string.
 *
 *---------------------------------------------------------
 */
void
GrDrawText (char *text, 
	    int x, int y, int rot) 
			         /* position of leftmost point of
			          * the baseline for this string.
			          */
{

  /* DEBUG
  fprintf(stderr,"DEBUG GrDrawText text='%s' x=%d y=%d rot=%d size=%d\n",
	  text,x,y,rot, grCurFontSize);

  if(grCurClipRect)
  {
    fprintf(stderr,"DEBUG GrDrawText clip: %d %d %d %d\n", 
	    grCurClipRect[0],
	    grCurClipRect[1],
	    grCurClipRect[2],
	    grCurClipRect[3]);
  }

  */

  /* transform coors */
  x = grMax2BufX(x); 
  y = grMax2BufY(y);

  if(grCurFontSize < 0) return;

  /* handle rotated text specially */
  if(rot != 0)
  {
    grRotTextDraw(text,x,y,rot);
  }
  else
  {
    XDrawString(grXdpy, grXWin, grXGC,  
		x,y,
		text,
		strlen(text));
  }
}

/*---------------------------------------------------------
 * GrFillPolygon -
 *
 *	Draw a polygon as a filled region.
 *
 *      Special case:  two point polygons specify ovals!
 *
 *---------------------------------------------------------
 */
void
GrFillPolygon(int size, double *coords)
{
  int i;
  XPoint xps[1000];

  assert(size<=1000);

  if(size<2) return;

  /* convert coords to X points */
  for(i=0; i<size; i++)
  {
    xps[i].x = grMax2BufX(*(coords++));
    xps[i].y = grMax2BufY(*(coords++));
  }

  if(size > 2)    
  {
    XFillPolygon(grXdpy, grXWin, grXGC,
		 xps, size, Nonconvex, CoordModeOrigin);
  }
  else
  {
    /* special case 2 point "polygon" = (complete) arc */

    int x, y, width, height;

    if(xps[0].x < xps[1].x)
    {
      x = xps[0].x;
      width = xps[1].x - x;
    }
    else
    {
      x = xps[1].x;
      width = xps[0].x - x;
    }	  

    if(xps[0].y < xps[1].y)
    {
      y = xps[0].y;
      height = xps[1].y - y;
    }
    else
    {
      y = xps[1].y;
      height = xps[0].y - y;
    }	  
	
    XFillArc(grXdpy, 
	     grXWin, 
	     grXGC, 
	     x, y, width, height,
	     0, 360*64);  /* angles */ 
  }
}


/*---------------------------------------------------------
 * GrCopyPixmap --
 *
 *	Copy rectangular region of src pixmap into current drawable.
 *
 *---------------------------------------------------------
 */
void  
GrCopyPixmap(void *src, 

	     int srcX0, int srcY0, 
	     int destX0, int destY0, 
	     int width, int height) 
{
  GrDrawable *srcGD = (GrDrawable *) src;

  /* flush pending graphics since may be order dependent */
  grFlushInternal();

  /* transform coords */
  srcX0 = srcX0;
  srcY0 = srcGD->gd_height - srcY0 - height;
  destX0 = grMax2BufX(destX0);
  destY0 = grMax2BufY(destY0+height-1);
/*
  fprintf(stderr,"srcX0=%d srcY0=%d, destX0=%d, destY0=%d, width=%d, height=%d\n",
	  srcX0, srcY0, destX0, destY0, width, height);
*/

  XCopyArea(grXdpy, srcGD->gd_drawable, grXWin, grXGC, 
	    srcX0, srcY0,
	    width, height,
	    destX0, destY0);
}

/*
 * ----------------------------------------------------------------------------
 *
 * GrAdjustStippleOrigin --
 *
 * adjust stipple origin to match default stipple origin of gd
 *
 * NOTE: result depends on size of current stipple, so need to call AFTER
 *       setting stipple.
 * 
 *
 * ----------------------------------------------------------------------------
 */
void GrAdjustStippleOrigin(void *gd, /* gd to match stipple to */
			   int x,    /* gd origin in current drawables coords */ 
			   int y)
{
  int xOff, yOff;
  Window stippleRoot;
  int stippleX, stippleY, stippleWidth, stippleHeight;
  int stippleBorder, stippleDepth;
    
  /* compute offset */
  assert(gd);
  xOff = grMax2BufX(x);
  yOff = grMax2BufY(y) - ((GrDrawable *) gd)->gd_height + 1;

  /* get current stipple geometry */
  assert(grCurStipple);
  XGetGeometry(grXdpy, 
	       *((Pixmap *) grCurStipple), 
	       &stippleRoot,
	       &stippleX,
	       &stippleY,
	       &stippleWidth,
	       &stippleHeight,
	       &stippleBorder,
	       &stippleDepth);
	       
  /* move offset to small positive value (just to be safe) */
  xOff = MODULO(xOff,stippleWidth);
  yOff = MODULO(yOff,stippleHeight);

  /* do it */
  grFlushInternal();
  XSetTSOrigin(grXdpy, grXGC, xOff, yOff); 
}


/*
 * ----------------------------------------------------------------------------
 *
 * GrDefaultStippleOrigin --
 *
 * restore default origin back to default.
 *
 * ----------------------------------------------------------------------------
 */
void GrDefaultStippleOrigin(void)
{
  grFlushInternal();
  XSetTSOrigin(grXdpy, grXGC, 0, 0); 
}


/*---------------------------------------------------------
 * GrCopyPlane --
 *
 *	Like GrCopyPixmap, but uses single plane in
 *      src pixmap mapping 0 and 1 bits to specified colors. 
 *
 *---------------------------------------------------------
 */
void  
GrCopyPlane(void *src, 
	    int srcPlaneMask,
	    int fgColor,               /* color for ones */
	    int bgColor,               /* color for zeros */ 
	    int srcX0, int srcY0, 
	    int destX0, int destY0, 
	    int width, int height) 
{
  GrDrawable *srcGD = (GrDrawable *) src;

  /* flush pending graphics before changing state 
   * (also may be order dependent)
   */
  grFlushInternal();

  if(GrColorMapped)
  {
    /* map from logical to physical bits */

    srcPlaneMask = grPixelsAll[srcPlaneMask] & ~grOtherAll;
 
    if(grCurWriteMask & 0200)
    {
      fgColor = grPixelsAll[fgColor];
      bgColor = grPixelsAll[bgColor];
    }
    else
    {
      fgColor = grPixelsColor[fgColor];
      bgColor = grPixelsColor[bgColor];
    }
  }

  /* DEBUG
  fprintf(stderr,"DEBUG grCopyPlane, fgcolor=%#o bgcolor=%#o\n",
	    fgColor,bgColor);
  */
  
  /* set colors */
  XSetForeground(grXdpy,grXGC,fgColor);
  XSetBackground(grXdpy,grXGC,bgColor);

  /* transform coords */
  srcX0 = srcX0;
  srcY0 = srcGD->gd_height - srcY0 - height;
  destX0 = grMax2BufX(destX0);
  destY0 = grMax2BufY(destY0+height-1);

/*
  fprintf(stderr,"srcX0=%d srcY0=%d, destX0=%d, destY0=%d, width=%d, height=%d\n",
	  srcX0, srcY0, destX0, destY0, width, height);
*/

  /* DEBUG
  if(Debug3)
  {
    fprintf(stderr,"DEBUG grCopyPlane, skipping XCopyPlane\n");
    fprintf(stderr,
	    "srcX0=%d srcY0=%d, width=%d height=%d, destX0=%d, destY0=%d mask=%#o\n",
	    srcX0,srcY0,width,height,destX0,destY0,srcPlaneMask);

  }
  else
  */
  {

    /* DEBUG
    fprintf(stderr,"DEBUG grCopyPlane, BEFORE XCopyPlane.\n");
    fprintf(stderr,
	    "srcX0=%d srcY0=%d, width=%d height=%d, destX0=%d, destY0=%d mask=%#o\n",
	    srcX0,srcY0,width,height,destX0,destY0,srcPlaneMask);
    fprintf(stderr,"srcHeight=%d srcWidth=%d\n",
	    srcGD->gd_height, srcGD->gd_width); 
    */

  /* copy plane */
  XCopyPlane(grXdpy, 
	     srcGD->gd_drawable, 
	     grXWin, 
	     grXGC,
	     srcX0, 
	     srcY0,
	     width,
	     height,
	     destX0, 
	     destY0,
	     srcPlaneMask);

  /* DEBUG
    fprintf(stderr,"DEBUG grCopyPlane, AFTER XCopyPlane.\n");
    */
  }
  
  /* restore colors */
  {
    int color = grCurColor;

    if(GrColorMapped)
    {
      if(grCurWriteMask & 0200)
      {
	color = grPixelsAll[color];
      }
      else
      {
	color = grPixelsColor[color];
      }
    }

    XSetForeground(grXdpy, grXGC, color);
  }
}









